import { useState } from 'react';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import NavbarItem from './ui/NavbarItem';
import Container from './ui/Container';

export default function Navbar() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <nav className="bg-white sticky top-0 z-50 shadow-sm">
      <Container>
        <div className="flex justify-between h-20 items-center">
          {/* Logo */}
          <motion.div 
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.6 }}
            className="flex-shrink-0 flex items-center">
            <Link to="/" className="text-2xl md:text-3xl font-bold font-serif tracking-wide text-gray-900">
              Elementum<span className="text-brand-purple text-4xl leading-none">.</span>
            </Link>
          </motion.div>

          {/* Desktop Nav */}
          <motion.div 
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.2 }}
            className="hidden md:flex space-x-10 items-center">
            <NavbarItem to="/" isActive={true}>Home</NavbarItem>
            <NavbarItem to="#studio">Studio</NavbarItem>
            <NavbarItem to="#services">Services</NavbarItem>
            <NavbarItem to="#contact">Contact</NavbarItem>
            <NavbarItem to="#faqs">FAQs</NavbarItem>
          </motion.div>

          {/* Mobile menu button */}
          <div className="md:hidden flex items-center">
            <button 
              onClick={() => setIsOpen(!isOpen)}
              className="text-gray-900 hover:text-brand-purple focus:outline-none shrink-0 p-2"
            >
              <svg className="h-7 w-7" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                {isOpen ? (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                ) : (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16m-7 6h7" />
                )}
              </svg>
            </button>
          </div>
        </div>
      </Container>

      {/* Mobile Menu Overlay */}
      <AnimatePresence>
        {isOpen && (
          <motion.div 
            initial={{ opacity: 0, height: 0, overflow: 'hidden' }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.4, ease: "easeInOut" }}
            className="md:hidden absolute top-20 left-0 w-full bg-white border-t border-gray-100 shadow-xl py-4 px-6 flex flex-col space-y-5 pb-8"
          >
            <NavbarItem to="/" isActive={true}>Home</NavbarItem>
            <NavbarItem to="#studio">Studio</NavbarItem>
            <NavbarItem to="#services">Services</NavbarItem>
            <NavbarItem to="#contact">Contact</NavbarItem>
            <NavbarItem to="#faqs">FAQs</NavbarItem>
          </motion.div>
        )}
      </AnimatePresence>
    </nav>
  );
}

import { motion } from 'framer-motion';

export default function Button({ children, variant = "primary", className = "", ...props }) {
  const baseStyle = "font-semibold transition-all shadow-sm inline-flex items-center justify-center";
  const variants = {
    primary: "bg-gray-900 text-white hover:bg-gray-800 shadow-xl shadow-gray-900/20 px-8 py-3.5 sm:px-10 sm:py-4 rounded-full text-base sm:text-lg",
    secondary: "bg-white text-gray-900 border-2 border-gray-200 hover:border-gray-900 px-8 py-3.5 sm:px-10 sm:py-4 rounded-full text-base sm:text-lg",
    text: "text-brand-purple hover:text-brand-purple/80 shadow-none px-0 py-0 text-base sm:text-lg group",
    textRed: "text-brand-red hover:text-brand-red/80 shadow-none px-0 py-0 text-base sm:text-lg group",
  };
  return (
    <motion.button 
      whileHover={{ scale: 1.02 }}
      whileTap={{ scale: 0.98 }}
      className={`${baseStyle} ${variants[variant] || variants.primary} ${className}`} 
      {...props}
    >
      {children}
    </motion.button>
  );
}

import { motion } from 'framer-motion';

export default function Card({ children, className = "", animate = true, ...props }) {
  if (!animate) {
    return (
      <div className={`bg-white p-8 md:p-12 rounded-2xl shadow-xl ${className}`} {...props}>
        {children}
      </div>
    );
  }

  return (
    <motion.div 
      initial={{ opacity: 0, scale: 0.95 }}
      whileInView={{ opacity: 1, scale: 1 }}
      viewport={{ once: true }}
      className={`bg-white p-8 md:p-12 rounded-2xl shadow-xl ${className}`}
      {...props}
    >
      {children}
    </motion.div>
  );
}

import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';

export default function NavbarItem({ to, children, isActive = false }) {
  const activeClass = isActive ? "text-gray-900 underline decoration-brand-purple decoration-2 underline-offset-4" : "text-gray-600 hover:text-gray-900";
  return (
    <Link to={to} className={`font-medium transition-colors ${activeClass} relative group`}>
      <motion.span 
        whileHover={{ scale: 1.05 }}
        whileTap={{ scale: 0.95 }}
        className="inline-block"
      >
        {children}
      </motion.span>
    </Link>
  );
}

import { motion } from 'framer-motion';

export default function SectionTitle({ children, className = "", align = "center" }) {
  const alignment = align === "center" ? "text-center" : align === "right" ? "text-right" : "text-left";
  return (
    <motion.h2 
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.8, ease: "easeOut" }}
      className={`text-4xl sm:text-5xl md:text-6xl font-serif text-gray-900 leading-[1.1] tracking-tight ${alignment} ${className}`}
    >
      {children}
    </motion.h2>
  );
}

